function groupBy(items, keyOf) {
  const out = {};
  for (const it of items) {
    const k = keyOf(it);
    (out[k] ??= []).push(it);
  }
  return out;
}

const people = [
  { name: "a", dept: "eng" },
  { name: "b", dept: "design" },
  { name: "c", dept: "eng" },
];
const g = groupBy(people, (p) => p.dept);
